# Converts your music for the custom-music Skate 3 build (generated by Claude for dekp23).
# Reads:  C:\Users\<you>\Music (all subfolders), the game's ipod.mpf / Ipod_Stream.mus (read only)
# Writes: C:\s3build\custom_music  (index, manifest, converted PCM)
# Progress: prepare_status.txt and prepare.log next to this script.

$ErrorActionPreference = 'Stop'
$Here     = Split-Path -Parent $MyInvocation.MyCommand.Path
$Install  = Split-Path -Parent $Here
$GameMus  = Join-Path $Install 'game\data\audio\music'
$Repo     = 'C:\s3build\skate3recomp'
$Tool     = Join-Path $Repo 'tools\skate3_music_import\skate3_music_import.py'
$MyMusic  = [Environment]::GetFolderPath('MyMusic')
$OutDir   = 'C:\s3build\custom_music'
$Log      = Join-Path $Here 'prepare.log'
$Status   = Join-Path $Here 'prepare_status.txt'

function Log([string]$m) {
  $line = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')  $m"
  Write-Host $line -ForegroundColor Cyan
  Add-Content -Path $Log -Value $line -Encoding UTF8
}
function Step([string]$m) {
  Log "STEP $m"
  Set-Content -Path $Status -Value "STEP $m  (since $(Get-Date -Format 'HH:mm:ss'))" -Encoding UTF8
}
function Run([string]$exe, [string[]]$argv) {
  Log "> $exe $($argv -join ' ')"
  $old = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
  & $exe @argv 2>&1 | ForEach-Object {
    $l = if ($_ -is [System.Management.Automation.ErrorRecord]) { $_.Exception.Message } else { "$_" }
    Write-Host $l; Add-Content -Path $Log -Value $l -Encoding UTF8
  }
  $code = $LASTEXITCODE; $ErrorActionPreference = $old
  if ($code -ne 0) { throw "$exe exited with code $code" }
}
function Refresh-Path {
  $env:Path = [Environment]::GetEnvironmentVariable('Path', 'Machine') + ';' +
              [Environment]::GetEnvironmentVariable('Path', 'User')
  foreach ($p in @('C:\Program Files\Git\cmd', "$env:LOCALAPPDATA\Microsoft\WinGet\Links")) {
    if ((Test-Path $p) -and ($env:Path -notlike "*$p*")) { $env:Path = "$p;$env:Path" }
  }
}
function Has([string]$cmd) { [bool](Get-Command $cmd -ErrorAction SilentlyContinue) }

try {
  Set-Content -Path $Log -Value "Skate3 custom music: prepare log" -Encoding UTF8
  Refresh-Path

  Step '1/4 updating tool code'
  Run 'git' @('-C', $Repo, 'fetch', 'origin', 'custom-music-import')
  Run 'git' @('-C', $Repo, 'checkout', '--', 'tools')
  Run 'git' @('-C', $Repo, 'merge', '--ff-only', 'origin/custom-music-import')
  Run 'git' @('-C', $Repo, 'log', '-1', '--oneline')

  Step '2/4 checking ffmpeg and python'
  if (-not (Has 'ffmpeg')) {
    Log 'installing FFmpeg (Gyan.FFmpeg) via winget'
    $old = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    & winget install --id Gyan.FFmpeg -e --source winget --accept-package-agreements --accept-source-agreements 2>&1 |
      ForEach-Object { $l = "$_"; Write-Host $l; Add-Content -Path $Log -Value $l -Encoding UTF8 }
    $ErrorActionPreference = $old
    Refresh-Path
  }
  if (-not (Has 'ffmpeg')) { throw 'ffmpeg still not found after install' }
  Run 'ffmpeg' @('-hide_banner', '-version')
  $py = if (Has 'py') { 'py' } elseif (Has 'python') { 'python' } else { throw 'Python not found' }

  Step '3/4 listing your music'
  Log "music folder: $MyMusic"
  $exts = '.mp3','.flac','.ogg','.oga','.opus','.m4a','.aac','.wav','.wma','.aiff','.aif','.alac','.ape','.wv','.webm','.mka','.mp4','.m4v','.mkv','.mov'
  $files = Get-ChildItem -Path $MyMusic -Recurse -File -ErrorAction SilentlyContinue |
           Where-Object { $exts -contains $_.Extension.ToLower() }
  foreach ($f in $files) { Log "  found: $($f.FullName.Substring($MyMusic.Length)) ($([math]::Round($f.Length/1MB,1)) MB)" }
  if (-not $files) { throw "no audio/video files found in $MyMusic" }

  Step '4/4 converting and assigning to the 46 iPod song slots'
  Run $py @('-X', 'utf8', $Tool, 'prepare', $GameMus, $MyMusic, '--out', $OutDir, '--fill', 'repeat')
  $pcm = Get-ChildItem $OutDir -Filter '*.pcm'
  Log "output: $($pcm.Count) PCM file(s), $([math]::Round(($pcm | Measure-Object Length -Sum).Sum/1MB,1)) MB in $OutDir"

  Log 'RESULT: SUCCESS'
  Set-Content -Path $Status -Value "RESULT: SUCCESS $(Get-Date -Format 'HH:mm:ss') -> $OutDir" -Encoding UTF8
  Write-Host "`nDone. Start C:\s3build\Skate3Recomp-CustomMusic\skate3.exe and open the in-game music player." -ForegroundColor Green
}
catch {
  $msg = $_.Exception.Message
  Log "RESULT: FAILED - $msg"
  Set-Content -Path $Status -Value "RESULT: FAILED $(Get-Date -Format 'HH:mm:ss') - $msg" -Encoding UTF8
  Write-Host "`nFAILED: $msg  (see $Log)" -ForegroundColor Red
  exit 1
}
